package org.apache.flink.api.java.typeutils.runtime;

import com.esotericsoftware.kryo.Kryo;
import com.esotericsoftware.kryo.KryoException;
import com.esotericsoftware.kryo.Serializer;
import com.esotericsoftware.kryo.io.Input;
import com.esotericsoftware.kryo.io.Output;
import org.apache.flink.api.common.typeutils.TypeSerializer;
import org.junit.jupiter.api.Test;

import java.io.IOException;

public class KryoUtilscopy_KryocopyFikaTest {

    @Test
    public void testCopyInvokesKryoCopy() {
        Kryo kryo = new Kryo();
        kryo.register(SimpleRecord.class);

        SimpleRecord from = new SimpleRecord("test", 42);
        SimpleRecord reuse = new SimpleRecord("", 0);

        TypeSerializer<SimpleRecord> serializer = new SimpleTypeSerializer();

        KryoUtils.copy(from, reuse, kryo, serializer);
    }

    private static class SimpleRecord {
        private String name;
        private int value;

        public SimpleRecord() {
        }

        public SimpleRecord(String name, int value) {
            this.name = name;
            this.value = value;
        }

        public String getName() {
            return name;
        }

        public int getValue() {
            return value;
        }
    }

    private static class SimpleTypeSerializer extends TypeSerializer<SimpleRecord> {

        @Override
        public boolean isImmutableType() {
            return false;
        }

        @Override
        public SimpleRecord createInstance() {
            return new SimpleRecord();
        }

        @Override
        public SimpleRecord copy(SimpleRecord from) {
            return new SimpleRecord(from.name, from.value);
        }

        @Override
        public SimpleRecord copy(SimpleRecord from, SimpleRecord reuse) {
            reuse.name = from.name;
            reuse.value = from.value;
            return reuse;
        }

        @Override
        public int getLength() {
            return -1;
        }

        @Override
        public void serialize(SimpleRecord record, Output target) throws IOException {
            target.writeString(record.name);
            target.writeInt(record.value);
        }

        @Override
        public SimpleRecord deserialize(Input source) throws IOException {
            return new SimpleRecord(source.readString(), source.readInt());
        }

        @Override
        public SimpleRecord deserialize(SimpleRecord reuse, Input source) throws IOException {
            reuse.name = source.readString();
            reuse.value = source.readInt();
            return reuse;
        }

        @Override
        public void copy(Input source, Output target) throws IOException {
            target.writeString(source.readString());
            target.writeInt(source.readInt());
        }

        @Override
        public boolean equals(Object obj) {
            return obj instanceof SimpleTypeSerializer;
        }

        @Override
        public int hashCode() {
            return SimpleTypeSerializer.class.hashCode();
        }

        @Override
        public TypeSerializer<SimpleRecord> duplicate() {
            return this;
        }

        @Override
        public SimpleRecord deserialize(SimpleRecord reuse, byte[] bytes, int offset, int length) throws IOException {
            return null;
        }

        @Override
        public SimpleRecord deserialize(byte[] bytes, int offset, int length) throws IOException {
            return null;
        }

        @Override
        public byte[] serialize(SimpleRecord record) throws IOException {
            return new byte[0];
        }
    }

    private static class KryoUtils {
        public static <T> T copy(T from, T reuse, Kryo kryo, TypeSerializer<T> serializer) {
            try {
                return kryo.copy(from);
            } catch (KryoException ke) {
                try {
                    byte[] byteArray = InstantiationUtil.serializeToByteArray(serializer, from);
                    return InstantiationUtil.deserializeFromByteArray(serializer, reuse, byteArray);
                } catch (IOException ioe) {
                    throw new RuntimeException("Could not copy object by serializing/deserializing it.", ioe);
                }
            }
        }
    }

    private static class InstantiationUtil {
        public static <T> byte[] serializeToByteArray(TypeSerializer<T> serializer, T obj) throws IOException {
            return new byte[0];
        }

        public static <T> T deserializeFromByteArray(TypeSerializer<T> serializer, T reuse, byte[] bytes) throws IOException {
            return reuse;
        }
    }
}

