package org.apache.flink.api.java.typeutils;

import org.apache.flink.api.common.typeutils.TypeSerializer;
import org.apache.flink.api.java.typeutils.PojoField;
import org.apache.flink.api.java.typeutils.PojoTypeInfo;
import org.apache.flink.api.java.typeutils.TypeExtractor;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class PojoTypeInfotoString_StringUtilsjoinFikaTest {

    @Test
    public void testToStringInvokesStringUtilsJoin() {
        // Create a real PojoTypeInfo instance
        PojoTypeInfo<TestPojo> pojoTypeInfo = (PojoTypeInfo<TestPojo>) TypeExtractor.getForClass(TestPojo.class);

        // Create mock PojoField objects
        List<PojoField> fields = new ArrayList<>();

        PojoField field1 = mock(PojoField.class);
        when(field1.getField()).thenReturn(TestPojo.class.getDeclaredFields()[0]);
        when(field1.getTypeInformation()).thenReturn(TypeExtractor.getForClass(String.class));

        PojoField field2 = mock(PojoField.class);
        when(field2.getField()).thenReturn(TestPojo.class.getDeclaredFields()[1]);
        when(field2.getTypeInformation()).thenReturn(TypeExtractor.getForClass(Integer.class));

        fields.add(field1);
        fields.add(field2);

        // Use reflection to set the fields in PojoTypeInfo
        try {
            java.lang.reflect.Field fieldsField = PojoTypeInfo.class.getDeclaredField("fields");
            fieldsField.setAccessible(true);
            fieldsField.set(pojoTypeInfo, fields);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Invoke toString which should call StringUtils.join
        pojoTypeInfo.toString();
    }

    // Simple test POJO class
    public static class TestPojo {
        public String name;
        public Integer age;

        public TestPojo() {}

        public TestPojo(String name, Integer age) {
            this.name = name;
            this.age = age;
        }
    }
}

