package org.apache.flink.api.java.typeutils.runtime.kryo;

import com.esotericsoftware.kryo.Kryo;
import com.esotericsoftware.kryo.io.Input;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;

public class JavaSerializerread_ObjectMapputFikaTest {

    @Test
    public void testReadInvokesObjectMapPut() throws Exception {
        Kryo kryo = new Kryo();
        kryo.setRegistrationRequired(false);

        byte[] serializedData = createSerializedObject();
        Input input = new Input(new ByteArrayInputStream(serializedData));

        JavaSerializer<Object> serializer = new JavaSerializer<>();

        kryo.readObject(input, Object.class, serializer);

        input.close();
    }

    private byte[] createSerializedObject() throws Exception {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        java.io.ObjectOutputStream oos = new java.io.ObjectOutputStream(baos);
        oos.writeObject("testObject");
        oos.close();
        return baos.toByteArray();
    }

    private static class JavaSerializer<T> extends com.esotericsoftware.kryo.Serializer<T> {
        @SuppressWarnings({ "unchecked", "rawtypes" })
        @Override
        public T read(Kryo kryo, Input input, Class aClass) {
            try {
                com.esotericsoftware.kryo.util.ObjectMap graphContext = kryo.getGraphContext();
                ObjectInputStream objectStream = ((ObjectInputStream) (graphContext.get(this)));
                if (objectStream == null) {
                    objectStream = new InstantiationUtil.ClassLoaderObjectInputStream(input, kryo.getClassLoader());
                    graphContext.put(this, objectStream);
                }
                return ((T) (objectStream.readObject()));
            } catch (Exception ex) {
                throw new com.esotericsoftware.kryo.KryoException("Error during Java deserialization.", ex);
            }
        }

        @Override
        public void write(Kryo kryo, com.esotericsoftware.kryo.io.Output output, T object) {
            throw new UnsupportedOperationException();
        }
    }

    private static class InstantiationUtil {
        static class ClassLoaderObjectInputStream extends ObjectInputStream {
            ClassLoaderObjectInputStream(Input input, ClassLoader classLoader) throws Exception {
                super(new ByteArrayInputStream(input.getBuffer(), input.position(), input.available()));
            }
        }
    }
}

