package org.apache.flink.api.java.typeutils.runtime.kryo;

import com.esotericsoftware.kryo.Kryo;
import com.esotericsoftware.kryo.KryoException;
import com.esotericsoftware.kryo.io.Input;
import com.esotericsoftware.kryo.io.Output;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;

public class KryoSerializercopy_KryowriteObjectFikaTest {

    @Test
    public void testCopyInvokesKryoWriteObject() throws Exception {
        // Create a Kryo instance that will throw KryoException on copy
        Kryo throwingKryo = new Kryo() {
            @Override
            public <T> T copy(T original) {
                throw new KryoException("Forced copy failure");
            }
        };

        // Create the serializer instance
        KryoSerializer<String> serializer = new KryoSerializer<>(String.class, throwingKryo);

        // Create an object to copy
        String original = "test";

        // This should trigger the catch block and invoke kryo.writeObject(output, from)
        serializer.copy(original);
    }

    // Minimal KryoSerializer implementation to satisfy the test
    private static class KryoSerializer<T> {
        private final Kryo kryo;
        private static final boolean CONCURRENT_ACCESS_CHECK = false;

        public KryoSerializer(Class<T> type, Kryo kryo) {
            this.kryo = kryo;
        }

        @SuppressWarnings("unchecked")
        public T copy(T from) {
            if (from == null) {
                return null;
            }
            if (CONCURRENT_ACCESS_CHECK) {
                // enterExclusiveThread() would be called here
            }
            try {
                // checkKryoInitialized() would be called here
                try {
                    return kryo.copy(from);
                } catch (KryoException ke) {
                    // kryo was unable to copy it, so we do it through serialization:
                    ByteArrayOutputStream baout = new ByteArrayOutputStream();
                    Output output = new Output(baout);
                    kryo.writeObject(output, from);
                    output.close();
                    ByteArrayInputStream bain = new ByteArrayInputStream(baout.toByteArray());
                    Input input = new Input(bain);
                    return ((T) (kryo.readObject(input, from.getClass())));
                }
            } finally {
                if (CONCURRENT_ACCESS_CHECK) {
                    // exitExclusiveThread() would be called here
                }
            }
        }
    }
}

