import java.io.ByteArrayOutputStream;

import static org.mockito.Mockito.*;

public class KryoSerializercopy_KryoreadObjectFikaTest {

    @Test
    public void testCopyInvokesKryoReadObject() throws Exception {
        // Create a real Kryo instance
        Kryo kryo = new Kryo();

        // Create a test object that will trigger KryoException during copy
        TestObject original = new TestObject("test-data");

        // Configure kryo to throw exception on copy to trigger the fallback path
        Kryo spyKryo = spy(kryo);
        when(spyKryo.copy(original)).thenThrow(new KryoException("Forced exception for test"));

