        kryoField.set(serializer, spyKryo);

        // Disable concurrent access check to simplify test
        java.lang.reflect.Field concurrentField = KryoSerializer.class.getDeclaredField("CONCURRENT_ACCESS_CHECK");
        concurrentField.setAccessible(true);
        concurrentField.set(serializer, false);

        // This should trigger the fallback path that calls kryo.readObject()
        serializer.copy(original);
    }

