    private static class KryoSerializer<T> {
        private final Class<T> type;
        private final Kryo kryo;
        private static final boolean CONCURRENT_ACCESS_CHECK = false;

        KryoSerializer(Class<T> type, Kryo kryo) {
            this.type = type;
            this.kryo = kryo;
        }

        @SuppressWarnings("unchecked")
