public static <T> T convertToList(Object rawValue, Class<?> atomicClass) {
    if (rawValue instanceof List) {
        return ((T) (rawValue));
    } else {
        try {
            List<Object> data = YamlParserUtils.convertToObject(rawValue.toString(), List.class);
