            if (atomicClass == Map.class) {
                return ((T) (data.stream().map(map -> convertToStringMap(((Map<Object, Object>) (map)))).collect(Collectors.toList())));
            }
            return ((T) (data.stream().map(s -> convertValue(s, atomicClass)).collect(Collectors.toList())));
        } catch (Exception e) {
            // Fallback to legacy pattern
            return convertToListWithLegacyProperties(rawValue, atomicClass);
        }
    }
}

