        when(mockTis.getNextTarEntry()).thenReturn(null);

        // Create a real target directory
        File targetDir = tempDir.toFile();

        // Create a subdirectory to simulate the directory structure
        File subDir = new File(targetDir, "testdir");
        subDir.mkdirs();

        // Create a dummy file entry inside the directory
