/**
 * Sets all relevant options contained in the {@link ReadableConfig} such as e.g. {@link PipelineOptions#CLOSURE_CLEANER_LEVEL}.
 *
 * <p>It will change the value of a setting only if a corresponding option was set in the {@code configuration}. If a key is not present, the current value of a field will remain untouched.
 *
 * @param configuration
 * 		a configuration to read the values from
 * @param classLoader
 * 		a class loader to use when loading classes
 */
public void configure(ReadableConfig configuration, ClassLoader classLoader) {
    configuration.getOptional(PipelineOptions.AUTO_GENERATE_UIDS).ifPresent(this::setAutoGeneratedUids);
    configuration.getOptional(PipelineOptions.AUTO_WATERMARK_INTERVAL).ifPresent(this::setAutoWatermarkInterval);
    configuration.getOptional(PipelineOptions.CLOSURE_CLEANER_LEVEL).ifPresent(this::setClosureCleanerLevel);
    configuration.getOptional(PipelineOptions.GLOBAL_JOB_PARAMETERS).ifPresent(this::setGlobalJobParameters);
    configuration.getOptional(MetricOptions.LATENCY_INTERVAL).ifPresent(interval -> setLatencyTrackingInterval(interval.toMillis()));
    configuration.getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_ENABLED).ifPresent(this::enablePeriodicMaterialize);
    configuration.getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_INTERVAL).ifPresent(this::setPeriodicMaterializeIntervalMillis);
    configuration.getOptional(StateChangelogOptions.MATERIALIZATION_MAX_FAILURES_ALLOWED).ifPresent(this::setMaterializationMaxAllowedFailures);
    configuration.getOptional(PipelineOptions.MAX_PARALLELISM).ifPresent(this::setMaxParallelism);
    configuration.getOptional(CoreOptions.DEFAULT_PARALLELISM).ifPresent(this::setParallelism);
    configuration.getOptional(PipelineOptions.OBJECT_REUSE).ifPresent(this::setObjectReuse);
    configuration.getOptional(TaskManagerOptions.TASK_CANCELLATION_INTERVAL).ifPresent(interval -> setTaskCancellationInterval(interval.toMillis()));
    configuration.getOptional(TaskManagerOptions.TASK_CANCELLATION_TIMEOUT).ifPresent(timeout -> setTaskCancellationTimeout(timeout.toMillis()));
    configuration.getOptional(ExecutionOptions.SNAPSHOT_COMPRESSION).ifPresent(this::setUseSnapshotCompression);
    configuration.getOptional(RestartStrategyOptions.RESTART_STRATEGY).ifPresent(s -> this.setRestartStrategy(configuration));
    configuration.getOptional(JobManagerOptions.SCHEDULER).ifPresent(t -> this.configuration.set(JobManagerOptions.SCHEDULER, t));
    serializerConfig.configure(configuration, classLoader);
}

@Internal
public void enablePeriodicMaterialize(boolean enabled) {
    configuration.set(StateChangelogOptions.PERIODIC_MATERIALIZATION_ENABLED, enabled);
}

@Internal
public void resetParallelism() {
    configuration.removeConfig(CoreOptions.DEFAULT_PARALLELISM);
}

private void setAutoGeneratedUids(boolean autoGeneratedUids) {
    configuration.set(PipelineOptions.AUTO_GENERATE_UIDS, autoGeneratedUids);
}

private void setGlobalJobParameters(Map<String, String> parameters) {
    configuration.set(PipelineOptions.GLOBAL_JOB_PARAMETERS, parameters);
}

@Internal
public void setMaterializationMaxAllowedFailures(int materializationMaxAllowedFailures) {
    configuration.set(StateChangelogOptions.MATERIALIZATION_MAX_FAILURES_ALLOWED, materializationMaxAllowedFailures);
}

/**
 * Sets the maximum degree of parallelism defined for the program.
 *
 * <p>The maximum degree of parallelism specifies the upper limit for dynamic scaling. It also
 * defines the number of key groups used for partitioned state.
 *
 * @param maxParallelism
 * 		Maximum degree of parallelism to be used for the program.
 */
@PublicEvolving
public void setMaxParallelism(int maxParallelism) {
    checkArgument(maxParallelism > 0, "The maximum parallelism must be greater than 0.");
    configuration.set(PipelineOptions.MAX_PARALLELISM, maxParallelism);
}

@Internal
public void setPeriodicMaterializeIntervalMillis(Duration periodicMaterializeInterval) {
    configuration.set(StateChangelogOptions.PERIODIC_MATERIALIZATION_INTERVAL, periodicMaterializeInterval);
}

private void setRestartStrategy(ReadableConfig configuration) {
    Map<String, String> map = configuration.toMap();
    Map<String, String> restartStrategyEntries = new HashMap<>();
    for (Map.Entry<String, String> entry : map.entrySet()) {
        if (entry.getKey().startsWith(RestartStrategyOptions.RESTART_STRATEGY_CONFIG_PREFIX)) {
            restartStrategyEntries.put(entry.getKey(), entry.getValue());
        }
    }
    this.configuration.addAll(Configuration.fromMap(restartStrategyEntries));
}

public void setUseSnapshotCompression(boolean useSnapshotCompression) {
    configuration.set(ExecutionOptions.SNAPSHOT_COMPRESSION, useSnapshotCompression);
}

