public T createInstance() {
    if (Modifier.isAbstract(type.getModifiers()) || Modifier.isInterface(type.getModifiers())) {
        return null;
    } else // PATH: Test should invoke the next KryoSerializer.checkKryoInitialized(...) [step in execution path]
