    TypeComparator<IN1> leftComparator = buildComparatorFor(0, executionConfig, leftInformation);
    TypeComparator<IN2> rightComparator = buildComparatorFor(1, executionConfig, rightInformation);
    TypeSerializer<IN1> leftSerializer = leftInformation.createSerializer(executionConfig.getSerializerConfig());
    TypeSerializer<IN2> rightSerializer = rightInformation.createSerializer(executionConfig.getSerializerConfig());
