    for (Map.Entry<String, DistributedCache.DistributedCacheEntry> file : files) {
        Future<Path> doNothing = new CompletedFuture(new Path(file.getValue().filePath));
        cachedFiles.put(file.getKey(), doNothing);
    }
}

